exercises.solution:
from dataclasses import dataclass


@dataclass
class Harvest:
    farmer: str
    crop: str
    kg: float
    price_per_kg: float = 50.0

    def value(self):
        return self.kg * self.price_per_kg


def best(harvests):
    if not harvests:
        return None
    return max(harvests, key=lambda h: h.value())

