exercises.solution:
from enum import Enum


class Light(Enum):
    RED = "red"
    GREEN = "green"
    YELLOW = "yellow"


NEXT = {Light.RED: Light.GREEN, Light.GREEN: Light.YELLOW, Light.YELLOW: Light.RED}


def next_light(light):
    return NEXT[light]


def can_go(light):
    return light is Light.GREEN


def parse(text):
    # Light("red") looks a member up by its value and raises ValueError if there is none
    return Light(text.strip().lower())

tests.check:
try:
    parse('blue')
    raise AssertionError('parse("blue") should raise ValueError')
except ValueError:
    pass

