exercises.solution:
from dataclasses import dataclass, field
from enum import Enum


class Status(Enum):
    WAITING = "waiting"
    IN_ROOM = "in room"
    DONE = "done"


@dataclass
class Visit:
    patient: str
    status: Status = Status.WAITING
    notes: list = field(default_factory=list)   # a new list for every visit


def call_next(visits):
    for v in visits:
        if v.status is Status.WAITING:
            v.status = Status.IN_ROOM
            return v
    return None


def finish(visit, note):
    if visit.status is not Status.IN_ROOM:
        raise ValueError(f"{visit.patient} is not in the room")
    visit.notes.append(note)
    visit.status = Status.DONE


def waiting_count(visits):
    return sum(1 for v in visits if v.status is Status.WAITING)


@dataclass(frozen=True)
class Bed:
    ward: str
    number: int

tests.check:
v = Visit('Amina')
assert v.status is Status.WAITING and v.notes == [], v
assert {s.name for s in Status} == {'WAITING', 'IN_ROOM', 'DONE'}

import dataclasses
b = Bed('A', 1)
try:
    b.number = 2
    raise AssertionError('Bed should be frozen')
except dataclasses.FrozenInstanceError:
    pass
beds = {Bed('A', 1): 'Amina'}
assert beds[Bed('A', 1)] == 'Amina', 'equal frozen beds work as the same dict key'
